// Parse Contextual Search Parameters
// Extracts query and context parameters for hierarchical parent/child search

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const input = item.json;

  // Build the search payload
  const searchPayload = {
    query: input.query || "",
    include_parents: input.include_parents !== false, // default true
    include_children: input.include_children !== false, // default true
    limit: input.limit !== undefined ? parseInt(input.limit) : 10,
    min_score: input.min_score !== undefined ? parseFloat(input.min_score) : 0.5,
    min_quality: input.min_quality !== undefined ? parseFloat(input.min_quality) : 0.5
  };

  // Validate query is not empty
  if (!searchPayload.query || searchPayload.query.trim() === "") {
    throw new Error("Query parameter is required and cannot be empty for contextual search");
  }

  // Validate limit
  if (searchPayload.limit < 1 || searchPayload.limit > 50) {
    throw new Error("Limit must be between 1 and 50");
  }

  outputs.push({ json: searchPayload });
}

return outputs;

// Format Contextual Search Results
// Formats hierarchical search results with parent/child relationships

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const response = item.json;

  // Check if we have results
  if (!response.results || response.results.length === 0) {
    outputs.push({
      json: {
        success: true,
        message: "No contextual results found. Try: (1) broader search terms, (2) lower min_score threshold, or (3) semantic search instead.",
        query: response.query || "",
        results_count: 0,
        results: [],
        hierarchical_structure: []
      }
    });
    continue;
  }

  // Format results with hierarchy information
  const formattedResults = response.results.map((result, index) => {
    return {
      rank: index + 1,
      document_code: result.document_id || "Unknown",
      title: result.document_name || "Untitled Document",
      department: result.department || "Unknown",
      document_type: result.document_type_category || "Unknown",
      version: result.version || "N/A",

      // Hierarchy information
      hierarchy_level: result.hierarchy_level || "unknown",
      is_parent: result.hierarchy_level === "parent",
      is_child: result.hierarchy_level === "child",
      parent_id: result.parent_id || null,

      // Content with hierarchy context
      content_snippet: result.content ? result.content.substring(0, 400) + "..." : "",
      full_section: result.full_section || null,

      relevance_score: result.score ? result.score.toFixed(3) : "N/A",
      quality_score: result.quality_score ? result.quality_score.toFixed(3) : "N/A",
      sharepoint_url: result.document_url || null,

      // Generate citation format
      citation: `**${result.document_id || "Unknown"}** (${
        result.document_name || "Untitled"
      }${result.version ? ", " + result.version : ""})${result.hierarchy_level ? " [" + result.hierarchy_level + "]" : ""}`
    };
  });

  // Build hierarchical structure (group children under parents)
  const hierarchicalStructure = buildHierarchy(formattedResults);

  // Create formatted response
  const formattedResponse = {
    success: true,
    search_type: "contextual",
    query: response.query || "",
    results_count: formattedResults.length,

    // Flat list of all results
    results: formattedResults,

    // Hierarchical structure for better presentation
    hierarchical_structure: hierarchicalStructure,

    // Statistics
    statistics: {
      parent_documents: formattedResults.filter(r => r.is_parent).length,
      child_sections: formattedResults.filter(r => r.is_child).length,
      total_results: formattedResults.length
    },

    // Generate summary
    summary: generateContextualSummary(formattedResults, hierarchicalStructure, response.query),

    // Metadata
    metadata: {
      search_time_ms: response.search_time_ms || null,
      total_documents_searched: response.total_points || null,
      min_score_threshold: response.min_score || 0.7,
      min_quality_threshold: response.min_quality || 0.95,
      includes_parents: response.include_parents !== false,
      includes_children: response.include_children !== false
    }
  };

  outputs.push({ json: formattedResponse });
}

// Helper function to build hierarchical structure
function buildHierarchy(results) {
  const hierarchy = [];
  const parentsMap = {};

  // First pass: identify all parents
  results.forEach(result => {
    if (result.is_parent) {
      const parentNode = {
        document: result,
        children: []
      };
      parentsMap[result.document_code] = parentNode;
      hierarchy.push(parentNode);
    }
  });

  // Second pass: attach children to parents
  results.forEach(result => {
    if (result.is_child && result.parent_id) {
      const parent = parentsMap[result.parent_id];
      if (parent) {
        parent.children.push(result);
      } else {
        // Child without parent in results - add as standalone
        hierarchy.push({
          document: result,
          children: [],
          orphaned: true
        });
      }
    } else if (!result.is_parent && !result.is_child) {
      // Standalone document
      hierarchy.push({
        document: result,
        children: []
      });
    }
  });

  return hierarchy;
}

// Helper function to generate summary
function generateContextualSummary(results, hierarchy, query) {
  if (results.length === 0) {
    return `No contextual results found for "${query}".`;
  }

  const parents = results.filter(r => r.is_parent);
  const children = results.filter(r => r.is_child);

  let summary = `Found ${results.length} contextual results for "${query}"\n\n`;
  summary += `Structure: ${parents.length} parent documents, ${children.length} child sections\n\n`;

  // Show top hierarchical results
  summary += "Top results with context:\n";
  const topHierarchy = hierarchy.slice(0, 3);
  topHierarchy.forEach((node, i) => {
    summary += `${i + 1}. ${node.document.citation}`;
    if (node.children.length > 0) {
      summary += ` (${node.children.length} subsections)`;
    }
    if (node.orphaned) {
      summary += " [orphaned - parent not in results]";
    }
    summary += "\n";
  });

  return summary;
}

return outputs;
